/* LibraMail — fallback DOMPurify minimal. Remplacer par DOMPurify officiel si souhaité. */
'use strict';
(function () {
  if (window.DOMPurify) return;
  const BLOCKED_TAGS = new Set(['script', 'iframe', 'object', 'embed', 'form', 'input', 'button', 'video', 'audio']);
  const URL_ATTRS = new Set(['href', 'src', 'xlink:href', 'formaction']);
  function sanitize(html) {
    const template = document.createElement('template');
    template.innerHTML = String(html || '');
    const walker = document.createTreeWalker(template.content, NodeFilter.SHOW_ELEMENT);
    const remove = [];
    while (walker.nextNode()) {
      const element = walker.currentNode;
      const tag = element.tagName.toLowerCase();
      if (BLOCKED_TAGS.has(tag)) {
        remove.push(element);
        continue;
      }
      for (const attr of [...element.attributes]) {
        const name = attr.name.toLowerCase();
        const value = String(attr.value || '').trim();
        if (name.startsWith('on') || name === 'srcdoc') {
          element.removeAttribute(attr.name);
          continue;
        }
        if (URL_ATTRS.has(name) && /^(javascript|vbscript|data):/i.test(value) && !/^data:image\//i.test(value)) {
          element.removeAttribute(attr.name);
        }
      }
    }
    remove.forEach(element => element.remove());
    return template.innerHTML;
  }
  window.DOMPurify = { sanitize };
})();
